SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, l.value, l.valueuom, l.charttime, l.valuenum, l.ref_range_lower, l.ref_range_upper, d.icd_code, d.icd_version, COUNT(CASE WHEN l.value < 36.0 THEN 1 END) AS low_temp_count, COUNT(CASE WHEN l.value BETWEEN 36.0 AND 37.9 THEN 1 END) AS high_temp_count, COUNT(CASE WHEN l.value >= 38.0 THEN 1 END) AS high_high_temp_count, COUNT(CASE WHEN d.icd_code = 'A23.9' THEN 1 END) AS aki_count FROM patients p JOIN icustays i ON p.subject_id = i.subject_id JOIN labevents l ON i.stay_id = l.stay_id JOIN diagnoses_icd d ON l.stay_id = d.hadm_id WHERE p.gender = 'F' AND p.anchor_age BETWEEN 62 AND 72 AND l.charttime BETWEEN l.intime AND l.intime + interval '24 hours' AND l.valueuom = '°C' GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, l.value, l.valueuom, l.charttime, l.valuenum, l.ref_range_lower, l.ref_range_upper, d.icd_code, d.icd_version ORDER BY l.charttime NULLS LAST;